INSERT INTO `models` VALUES (1,'gpt-5.5','[New Flagship] GPT-5.5 can understand your goals faster and take on more of the work itself. It excels at writing and debugging code, online research, data analysis, creating documents and spreadsheets, operating software, and switching across tools until the task is completed. Instead of managing every step, you can give GPT-5.5 a messy multi-part task and trust it to plan, use tools, check work, navigate ambiguity, and keep moving forward.\n[全新旗舰版] GPT-5.5 能更快理解你的目标，并主动承担更多工作。它擅长编写和调试代码、开展线上调研、进行数据分析、制作文档和电子表格、操作各类软件，还能在不同工具间切换直至完成任务。你无需把控每一个步骤，只需交给 GPT-5.5 一项复杂的多部分任务，就能放心它会做好规划、使用工具、核查成果、应对模糊情况并持续推进。','import { OpenAI } from \'@lobehub/icons\';','',1,'{\n  \"openai\": {\n    \"path\": \"/v1/chat/completions\",\n    \"method\": \"POST\"\n  },\n  \"openai-response\": {\n    \"path\": \"/v1/responses\",\n    \"method\": \"POST\"\n  },\n  \"openai-response-compact\": {\n    \"path\": \"/v1/responses/compact\",\n    \"method\": \"POST\"\n  },\n  \"image-generation\": {\n    \"path\": \"/v1/images/generations\",\n    \"method\": \"POST\"\n  }\n}',1,1,1782402696,1782402928,NULL,0),(2,'gpt-5.3-codex-spark','[Disable reasoning, otherwise error will occur] GPT-5.3-Codex-Spark is a smaller, latency-optimized variant designed to provide an interactive, real-time coding experience. Co-developed with Cerebras\' wafer-scale hardware, Spark delivers throughput of over 1,000 tokens per second and an initial 128k token context window. It is positioned as a companion model: extremely fast on inline edits, boilerplate generation, quick refactoring, and short-hop tasks—but intentionally lighter on reasoning depth than the standard Codex.\n[禁用推理，否则将出现错误] GPT-5.3-Codex-Spark 是一款经过优化、延迟更低的小型变体，旨在提供交互式的实时编码体验。该模型与 Cerebras 的晶圆级硬件联合开发，每秒可处理超过1000个词元，初始上下文窗口可达12.8万个词元。它被定位为辅助模型：在内联编辑、样板代码生成、快速重构和短任务处理上速度极快，但在推理深度上刻意比标准 Codex 更轻量化。','import { OpenAI } from \'@lobehub/icons\';','',1,'{\n  \"openai\": {\n    \"path\": \"/v1/chat/completions\",\n    \"method\": \"POST\"\n  },\n  \"openai-response\": {\n    \"path\": \"/v1/responses\",\n    \"method\": \"POST\"\n  },\n  \"openai-response-compact\": {\n    \"path\": \"/v1/responses/compact\",\n    \"method\": \"POST\"\n  },\n  \"image-generation\": {\n    \"path\": \"/v1/images/generations\",\n    \"method\": \"POST\"\n  }\n}',1,1,1782402786,1782402911,NULL,0),(3,'gpt-5.4','[Mainstream Model] GPT-5.4 is a new generation large language model released by OpenAI on March 5, 2026, positioned as a cutting-edge model for professional work. The model integrates native computer operation capabilities, capable of understanding the screen through vision and simulating keyboard and mouse operations to execute complex workflows. It supports a context window of up to 1 million tokens and integrates multiple core capabilities such as deep reasoning, advanced programming, and efficient tool calling.\n[主流模型] GPT-5.4 是 OpenAI 于 2026 年 3 月 5 日发布的新一代大语言模型，定位为面向专业工作的前沿模型。该模型集成了原生的计算机操作能力，可通过视觉理解屏幕内容，并模拟键盘和鼠标操作来执行复杂的工作流程。它支持高达 100 万令牌的上下文窗口，还整合了深度推理、高级编程、高效工具调用等多项核心能力。','import { OpenAI } from \'@lobehub/icons\';','',1,'{\n  \"openai\": {\n    \"path\": \"/v1/chat/completions\",\n    \"method\": \"POST\"\n  },\n  \"openai-response\": {\n    \"path\": \"/v1/responses\",\n    \"method\": \"POST\"\n  },\n  \"openai-response-compact\": {\n    \"path\": \"/v1/responses/compact\",\n    \"method\": \"POST\"\n  },\n  \"image-generation\": {\n    \"path\": \"/v1/images/generations\",\n    \"method\": \"POST\"\n  }\n}',1,1,1782402992,1782402992,NULL,0),(4,'deepseek-v4-pro','[New Flagship] DS-V4-Pro has a total of 1.6 trillion parameters, with 49B activated parameters, mainly oriented towards cutting-edge tasks, with performance comparable to top closed-source models.\n[全新旗舰] DS-V4-Pro 总参数达1.6万亿，激活参数490亿，主要面向前沿任务，性能可与顶级闭源模型媲美。','import { DeepSeek } from \'@lobehub/icons\';','',2,'{\n  \"openai\": {\n    \"path\": \"/v1/chat/completions\",\n    \"method\": \"POST\"\n  },\n  \"openai-response\": {\n    \"path\": \"/v1/responses\",\n    \"method\": \"POST\"\n  },\n  \"openai-response-compact\": {\n    \"path\": \"/v1/responses/compact\",\n    \"method\": \"POST\"\n  },\n  \"image-generation\": {\n    \"path\": \"/v1/images/generations\",\n    \"method\": \"POST\"\n  }\n}',1,1,1782403176,1782403176,NULL,0),(5,'deepseek-v4-flash','[Mainstream Model] DS-V4-Flash has a total of 284 billion parameters, with 13B activated parameters, positioned as an economical choice.\n[主流模型] DS-V4-Flash 总共有 2840 亿个参数，激活参数为 130 亿，定位为经济之选。','import { DeepSeek } from \'@lobehub/icons\';','',2,'{\n  \"openai\": {\n    \"path\": \"/v1/chat/completions\",\n    \"method\": \"POST\"\n  },\n  \"openai-response\": {\n    \"path\": \"/v1/responses\",\n    \"method\": \"POST\"\n  },\n  \"openai-response-compact\": {\n    \"path\": \"/v1/responses/compact\",\n    \"method\": \"POST\"\n  },\n  \"image-generation\": {\n    \"path\": \"/v1/images/generations\",\n    \"method\": \"POST\"\n  }\n}',1,1,1782403251,1782403251,NULL,0);
